/**
 * Shared utilities for Node.js Lambda functions in this stack.
 *
 * Bundled as a Lambda Layer (see JsSharedLayer in functions.ts) so each
 * function can `import { ... } from 'grantwell-shared'` without duplicating
 * security-sensitive helpers across asset folders.
 */

import { createHmac, timingSafeEqual } from "node:crypto";

/**
 * Standard CORS headers for HTTP API responses. Origin is "*" today; a future neutral-core config
 * axis can narrow this per deployment. Exported so handlers stop re-inlining the literal.
 */
export const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Content-Type": "application/json",
};

/** Uniform JSON HTTP response with CORS headers. */
export function jsonResponse(statusCode, body) {
  return {
    statusCode,
    headers: corsHeaders,
    body: JSON.stringify(body),
  };
}

/**
 * Supported states for this deployment, injected as SUPPORTED_STATES ([{code,name}]) by the CDK
 * stack (sourced from lib/shared/states.ts). Parsed once here so handlers don't each re-parse it.
 * Falls back to [] so a missing env var degrades gracefully rather than throwing at import time.
 */
function parseSupportedStates() {
  try {
    const parsed = JSON.parse(process.env.SUPPORTED_STATES || "[]");
    if (!Array.isArray(parsed)) return [];
    return parsed
      .map((s) => (s && typeof s === "object" ? { code: s.code, name: s.name } : null))
      .filter((s) => s && typeof s.code === "string");
  } catch {
    return [];
  }
}

const SUPPORTED_STATES = parseSupportedStates();
const STATE_NAME_BY_CODE = new Map(SUPPORTED_STATES.map((s) => [s.code, s.name]));

/** Set of supported state codes for membership checks. */
export function getSupportedStateCodes() {
  return new Set(STATE_NAME_BY_CODE.keys());
}

/** Full display name for a state code (e.g. "MA" -> "Massachusetts"), or the code if unknown. */
export function stateNameFromCode(code) {
  return STATE_NAME_BY_CODE.get(code) || code;
}

export function parseRoles(raw) {
  if (Array.isArray(raw)) return raw.filter((r) => typeof r === "string");
  if (typeof raw !== "string" || raw.trim() === "") return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.filter((r) => typeof r === "string") : [];
  } catch {
    return [];
  }
}

export function requireAdmin(event) {
  if (!event?.requestContext) return null;
  const claims = event.requestContext.authorizer?.jwt?.claims || {};
  const roles = parseRoles(claims["custom:role"]);
  if (!roles.includes("Admin") && !roles.includes("Developer")) {
    return jsonResponse(403, { error: "Forbidden: Admin role required" });
  }
  return null;
}

/**
 * The caller's edit authority over NOFOs, from their JWT claims:
 *   developer / regularAdmin (admin, no state) — may edit any NOFO
 *   stateAdmin (admin + a supported custom:state) — may edit only their own state's NOFOs
 *   user — no edit authority
 */
export function resolveCallerScope(event) {
  const claims = event?.requestContext?.authorizer?.jwt?.claims || {};
  const roles = parseRoles(claims["custom:role"]);
  const stateRaw = String(claims["custom:state"] || "").trim().toUpperCase();
  const state = getSupportedStateCodes().has(stateRaw) ? stateRaw : "";

  if (roles.includes("Developer")) return { role: "developer", state };
  if (roles.includes("Admin")) {
    return state ? { role: "stateAdmin", state } : { role: "regularAdmin", state: "" };
  }
  return { role: "user", state };
}

/**
 * Throw a 403-bearing Error unless `callerScope` may edit a NOFO with the given scope/state.
 * Developers and stateless admins pass; a state admin passes only for their own state's NOFOs.
 */
export function assertCanEditNofo(callerScope, nofoScope, nofoState) {
  if (callerScope.role === "developer" || callerScope.role === "regularAdmin") return;
  if (callerScope.role === "stateAdmin") {
    if (nofoScope === "state" && nofoState === callerScope.state) return;
    const err = new Error(
      nofoScope === "federal"
        ? "State admins cannot modify federal NOFOs."
        : "State admins can only modify NOFOs for their own state."
    );
    err.statusCode = 403;
    throw err;
  }
  const err = new Error("Not authorized to modify NOFOs.");
  err.statusCode = 403;
  throw err;
}

/**
 * Read a NOFO's scope/state from the metadata table. `resolved` distinguishes "the row genuinely
 * records no scope" from "we could not read it" (missing table/name or a DynamoDB error) so callers
 * can fail closed on the unknown case. Requires a DynamoDBClient + GetItemCommand + unmarshall
 * passed in, keeping this layer free of an @aws-sdk dependency.
 */
export async function readNofoScope(deps, tableName, nofoName) {
  const { client, GetItemCommand, marshall, unmarshall } = deps || {};
  if (!client || !tableName || !nofoName) return { scope: null, state: null, resolved: false };
  try {
    const result = await client.send(
      new GetItemCommand({ TableName: tableName, Key: marshall({ nofo_name: nofoName }) })
    );
    if (!result.Item) return { scope: null, state: null, resolved: true };
    const row = unmarshall(result.Item);
    return {
      scope: typeof row.scope === "string" ? row.scope : null,
      state: typeof row.state === "string" ? row.state : null,
      resolved: true,
    };
  } catch (err) {
    console.warn(`Could not read scope/state for ${nofoName}:`, err.message);
    return { scope: null, state: null, resolved: false };
  }
}

/**
 * Full fail-closed gate for a mutating NOFO endpoint: resolve the caller, read the NOFO's scope,
 * and enforce edit authority. When the NOFO's scope can't be determined (unrecorded/legacy row or
 * a read failure), a state admin is denied — only developers/stateless admins pass. Returns null
 * when allowed, or a 403 HTTP response object when denied (so handlers can `return` it directly).
 *
 * `opts.allowUnknownScope` (default false) exists for the create path, where the row may not exist
 * yet and scope was already enforced upstream at presign time.
 */
export async function assertCanEditNofoOr403(event, deps, tableName, nofoName, opts = {}) {
  const callerScope = resolveCallerScope(event);
  const { scope, state } = await readNofoScope(deps, tableName, nofoName);
  try {
    if (scope) {
      assertCanEditNofo(callerScope, scope, state);
    } else if (callerScope.role === "stateAdmin" && !opts.allowUnknownScope) {
      const err = new Error("Cannot verify NOFO scope; modification not permitted for state admins.");
      err.statusCode = 403;
      throw err;
    }
    return null;
  } catch (authError) {
    return jsonResponse(authError.statusCode || 403, { message: authError.message });
  }
}

/**
 * Returns the authenticated caller's Cognito sub from the API Gateway JWT
 * authorizer, or null when no requestContext is present.
 */
export function getAuthenticatedUserId(event) {
  return (
    event?.requestContext?.authorizer?.jwt?.claims?.sub ||
    event?.requestContext?.authorizer?.claims?.sub ||
    null
  );
}

function b64url(buf) {
  return Buffer.from(buf).toString("base64").replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function unsubscribeSignature(userId, secret) {
  return b64url(createHmac("sha256", secret).update(String(userId)).digest());
}

/** Signed, URL-safe unsubscribe token for a user. Returns "" if no secret is configured. */
export function makeUnsubscribeToken(userId, secret) {
  if (!secret || !userId) return "";
  return `${b64url(String(userId))}.${unsubscribeSignature(userId, secret)}`;
}

/** Verify a token; returns the user_id on a valid signature, else null. Constant-time compare. */
export function verifyUnsubscribeToken(token, secret) {
  if (!secret || typeof token !== "string" || !token.includes(".")) return null;
  const [idPart, sig] = token.split(".");
  let userId;
  try {
    userId = Buffer.from(idPart.replace(/-/g, "+").replace(/_/g, "/"), "base64").toString("utf8");
  } catch {
    return null;
  }
  if (!userId) return null;
  const expected = unsubscribeSignature(userId, secret);
  const a = Buffer.from(sig || "");
  const b = Buffer.from(expected);
  if (a.length !== b.length || !timingSafeEqual(a, b)) return null;
  return userId;
}

// HTML sanitization for content that gets rendered through headless Chromium
// (PDF generator) or html-to-docx. Untrusted <script>/<iframe>/<style>/event
// handlers in this position would execute in the renderer with the Lambda's
// network and credential context. Strip dangerous elements with their bodies,
// drop attributes off the remaining tags, and keep only a small allowlist of
// safe formatting tags.
const ALLOWED_CONTENT_TAGS = new Set([
  "p", "br", "strong", "b", "em", "i", "u", "s", "strike",
  "ul", "ol", "li",
  "h1", "h2", "h3", "h4", "h5", "h6",
  "blockquote", "span", "div", "hr", "pre", "code", "sub", "sup",
  "table", "thead", "tbody", "tr", "td", "th",
]);

const DANGEROUS_TAGS_WITH_CONTENT = [
  "script", "style", "iframe", "object", "embed", "noscript",
  "form", "svg", "math", "template", "link", "meta", "base",
];

export function sanitizeContentHtml(input) {
  if (input == null) return "";
  let s = String(input);

  for (const tag of DANGEROUS_TAGS_WITH_CONTENT) {
    s = s.replace(new RegExp(`<${tag}\\b[\\s\\S]*?</${tag}\\s*>`, "gi"), "");
    s = s.replace(new RegExp(`<${tag}\\b[^>]*/?>`, "gi"), "");
  }

  s = s.replace(/<!--[\s\S]*?-->/g, "");

  s = s.replace(/<\/?([a-zA-Z][a-zA-Z0-9]*)\b[^>]*>/g, (match, tagName) => {
    const lower = tagName.toLowerCase();
    if (!ALLOWED_CONTENT_TAGS.has(lower)) return "";
    return match.startsWith("</") ? `</${lower}>` : `<${lower}>`;
  });

  return s;
}

// --- NOFO digest email template (pure; shared by digest send + Developer preview) ---
export function escapeDigestHtml(s) {
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function formatDigestDate(value) {
  if (!value) return "";
  // Support "YYYY-MM-DD" and ISO; render as e.g. "Aug 1, 2026".
  const d = /^\d{4}-\d{2}-\d{2}$/.test(value)
    ? new Date(`${value}T00:00:00Z`)
    : new Date(value);
  if (isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
    timeZone: "UTC",
  });
}

function digestMeta(nofo) {
  // Labeled "Department: X · Category: Y" parts so the bare values aren't ambiguous; omit empties.
  const parts = [];
  if (nofo.agency) parts.push(`Department: ${nofo.agency}`);
  if (nofo.category) parts.push(`Category: ${nofo.category}`);
  const due = formatDigestDate(nofo.expiration_date);
  if (due) parts.push(`Deadline: ${due}`);
  return parts;
}

/**
 * Bridge the two digest modes into one list of `{ key, title, showHeading, items }` where each
 * item is `{ nofo, reasons, daysUntil }`. Flat mode (no `sections`) yields a single unheaded
 * section wrapping the bare `nofos` — so the classic digest renders identically. Sectioned mode
 * maps the { new, closingSoon, stillOpen } buckets from selectDigestSections into titled groups,
 * dropping empties. Headings show only when more than one non-empty section survives.
 */
function normalizeDigestSections(sections, flatNofos) {
  if (!sections) {
    return [{ key: "new", title: "", showHeading: false, items: (flatNofos || []).map((n) => ({ nofo: n, reasons: [], daysUntil: null })) }];
  }
  const defs = [
    { key: "new", title: "New this period", items: sections.new },
    { key: "closingSoon", title: "Closing soon", items: sections.closingSoon },
    { key: "stillOpen", title: "Still open", items: sections.stillOpen },
  ];
  const nonEmpty = defs
    .map((d) => ({ ...d, items: Array.isArray(d.items) ? d.items : [] }))
    .filter((d) => d.items.length);
  const showHeading = nonEmpty.length > 1;
  return nonEmpty.map((d) => ({ ...d, showHeading }));
}

/** Small colored deadline chip; red under a week, amber under a month, grey otherwise. "" if unknown. */
function deadlineChipHtml(daysUntil) {
  if (daysUntil == null || daysUntil < 0) return "";
  const bg = daysUntil <= 7 ? "#b91c1c" : daysUntil <= 30 ? "#b45309" : "#4b5563";
  const label = daysUntil === 0 ? "Closes today" : `Closes in ${daysUntil} day${daysUntil === 1 ? "" : "s"}`;
  return ` <span style="display:inline-block;background:${bg};color:#fff;font-size:11px;font-weight:600;padding:1px 6px;border-radius:10px;vertical-align:middle;">${label}</span>`;
}

/**
 * Digest email. nofos are full NOFO records (nofo_name, agency, category,
 * expiration_date). frequency: "daily"|"weekly".
 * opts:
 *   appUrl      base app URL for grant links
 *   profileUrl  "manage preferences" link (defaults to `${appUrl}/profile`)
 *   unsubscribeUrl  one-click unsubscribe link; also drives the List-Unsubscribe header at send
 *   dateRange   optional {from, to} ISO strings for the intro line
 *   copy        admin overrides: { subject, intro, footer }
 *   branding    { appName, brandColor, logoUrl, postalAddress } — optional; renders a header bar
 * returns {subject, html, text}
 */
export function buildDigest(nofos, frequency, opts = {}) {
  const label = frequency === "weekly" ? "weekly" : "daily";
  const appUrl = (opts.appUrl || "").replace(/\/+$/, "");
  const profileUrl = opts.profileUrl || (appUrl ? `${appUrl}/profile` : "");
  const copy = opts.copy || {};
  const branding = opts.branding || {};
  // Only accept a simple hex color; anything else falls back to the default brand green.
  const brandColor = /^#[0-9a-fA-F]{3,8}$/.test(branding.brandColor || "")
    ? branding.brandColor
    : "#195C53";
  const appName = branding.appName ? String(branding.appName) : "";
  const logoUrl = /^https?:\/\//.test(branding.logoUrl || "") ? branding.logoUrl : "";
  // CAN-SPAM requires a physical postal address in every commercial/notification email. Injected
  // from instance config at deploy; rendered in the footer when present.
  const postalAddress = branding.postalAddress ? String(branding.postalAddress) : "";
  const supportEmail = branding.supportEmail ? String(branding.supportEmail) : "";
  const brandName = appName || "GrantWell";
  const nofoLink = (name) =>
    appUrl ? `${appUrl}/requirements/${encodeURIComponent(name || "")}` : "";

  const rangeFrom = formatDigestDate(opts.dateRange?.from);
  const rangeTo = formatDigestDate(opts.dateRange?.to);
  const rangeText = rangeFrom && rangeTo ? ` (${rangeFrom}–${rangeTo})` : "";

  // Sectioned mode (opts.sections present) groups grants into New / Closing soon / Still open and
  // shows a per-grant match reason. Flat mode (no opts.sections) renders exactly the classic digest
  // — this keeps the env-flag-off path byte-for-byte unchanged.
  const sections = normalizeDigestSections(opts.sections, nofos);
  const newCount = opts.sections
    ? opts.sections.newTotal ?? opts.sections.new?.length ?? 0
    : nofos.length;
  const SUBJECT_COUNT_CAP = 25;
  const newCountLabel = newCount > SUBJECT_COUNT_CAP ? `${SUBJECT_COUNT_CAP}+` : `${newCount}`;
  const oppWord = newCount === 1 ? "opportunity" : "opportunities";

  const digestTitle = `${label === "weekly" ? "Weekly" : "Daily"} Digest`;
  const subject =
    copy.subject ||
    (newCount > 0
      ? `${brandName} ${digestTitle}: ${newCountLabel} new grant ${oppWord}`
      : `${brandName} ${digestTitle}: grant opportunities closing soon`);
  // Range is only worth the words on a fallback day, where it explains "no new grants THIS period".
  const intro =
    copy.intro ||
    (newCount > 0
      ? `We found ${newCountLabel} new grant ${oppWord} matching your preferences.`
      : `No new grants this ${label === "weekly" ? "week" : "day"}${rangeText}, but here are relevant opportunities worth a look.`);
  const footer =
    copy.footer ||
    `You received this email because you subscribed to ${brandName} grant opportunity notifications.`;

  // ---- plain text ----
  const textForItem = (item) => {
    const n = item.nofo;
    const name = n.nofo_name || "Untitled";
    const meta = digestMeta(n);
    const link = nofoLink(name);
    const metaLine = meta.length ? `  ${meta.join(" · ")}\n` : "";
    const reasonLine = item.reasons?.length ? `  Matched on: ${item.reasons.join(", ")}\n` : "";
    return `- ${name}\n${metaLine}${reasonLine}${link ? `  View grant opportunity: ${link}\n` : ""}`;
  };
  const textRows = sections
    .filter((s) => s.items.length)
    .map((s) => {
      const heading = s.showHeading ? `${s.title}\n` : "";
      return `${heading}${s.items.map(textForItem).join("\n")}`;
    })
    .join("\n\n");
  const textFooterLink = profileUrl ? `\nManage your preferences: ${profileUrl}\n` : "";
  const textUnsub = opts.unsubscribeUrl ? `Unsubscribe: ${opts.unsubscribeUrl}\n` : "";
  const textSupport = supportEmail ? `Questions? Contact ${supportEmail}\n` : "";
  const textAddress = postalAddress ? `\n${postalAddress}\n` : "";
  // When the display cap hid matches, point to the full list rather than growing the email.
  const overflow = opts.sections?.overflow ?? 0;
  const overflowText = overflow > 0 ? `+${overflow} more matching grant${overflow === 1 ? "" : "s"}` : "";
  const textOverflow = overflow > 0 ? `\n${overflowText}${appUrl ? ` — view all: ${appUrl}` : ""}\n` : "";
  const text = `${intro}\n\n${textRows}\n${textOverflow}${textFooterLink}${textUnsub}${textSupport}\n${footer}\n${textAddress}`;

  // ---- html (email-safe: tables + inline styles) ----
  // Each grant is a bordered card: prominent title, labeled meta, deadline chip, match reason, and
  // an explicit CTA so the action isn't hidden behind the title alone.
  const htmlForItem = (item) => {
    const n = item.nofo;
    const name = escapeDigestHtml(n.nofo_name || "Untitled");
    const link = nofoLink(n.nofo_name || "");
    const title = link
      ? `<a href="${link}" style="color:${brandColor};text-decoration:none;font-size:16px;font-weight:700;line-height:1.3;">${name}</a>`
      : `<span style="font-size:16px;font-weight:700;line-height:1.3;">${name}</span>`;
    const chip = deadlineChipHtml(item.daysUntil);
    const meta = digestMeta(n).map(escapeDigestHtml).join(" &middot; ");
    const metaHtml = meta
      ? `<div style="color:#5a5a5a;font-size:13px;margin-top:6px;">${meta}</div>`
      : "";
    const reasonHtml = item.reasons?.length
      ? `<div style="color:${brandColor};font-size:12px;margin-top:6px;">Matched on: ${item.reasons.map(escapeDigestHtml).join(" &middot; ")}</div>`
      : "";
    const ctaHtml = link
      ? `<div style="margin-top:10px;"><a href="${link}" style="color:${brandColor};text-decoration:none;font-size:13px;font-weight:600;">View grant opportunity &rarr;</a></div>`
      : "";
    return `<tr><td style="padding:6px 0;"><table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="border-collapse:separate;"><tr><td style="border:1px solid #e0e0e0;border-radius:8px;padding:16px;background:#ffffff;">${title}${chip}${metaHtml}${reasonHtml}${ctaHtml}</td></tr></table></td></tr>`;
  };
  const rows = sections
    .filter((s) => s.items.length)
    .map((s) => {
      const heading = s.showHeading
        ? `<tr><td style="padding:20px 0 6px;font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;color:#6b7280;">${escapeDigestHtml(s.title)}</td></tr>`
        : "";
      return `${heading}${s.items.map(htmlForItem).join("")}`;
    })
    .join("");

  const overflowHtml =
    overflow > 0 && appUrl
      ? `<tr><td style="padding:14px 0 2px;"><a href="${appUrl}" style="color:${brandColor};text-decoration:none;font-size:14px;font-weight:600;">${escapeDigestHtml(overflowText)} &mdash; view all &rarr;</a></td></tr>`
      : overflow > 0
      ? `<tr><td style="padding:14px 0 2px;font-size:14px;color:#4b5563;">${escapeDigestHtml(overflowText)}</td></tr>`
      : "";

  const unsubHtml = opts.unsubscribeUrl
    ? ` &middot; <a href="${escapeDigestHtml(opts.unsubscribeUrl)}" style="color:${brandColor};">Unsubscribe</a>`
    : "";
  const footerLinkHtml = profileUrl || unsubHtml
    ? `<p style="margin:16px 0 4px;">${profileUrl ? `<a href="${profileUrl}" style="color:${brandColor};">Manage your preferences</a>` : ""}${unsubHtml}</p>`
    : "";
  const supportHtml = supportEmail
    ? `<p style="color:#6b7280;font-size:12px;margin:4px 0 0;">Questions? Contact <a href="mailto:${escapeDigestHtml(supportEmail)}" style="color:${brandColor};">${escapeDigestHtml(supportEmail)}</a></p>`
    : "";
  const addressHtml = postalAddress
    ? `<p style="color:#6b7280;font-size:12px;margin:4px 0 0;">${escapeDigestHtml(postalAddress)}</p>`
    : "";

  const headerTitle = digestTitle;
  // Scannable one-liner: "N new opportunities for you" on a normal day, deadline framing on a
  // fallback day. Uses the true (pre-cap) counts so it reads honestly even when the body is capped.
  const closingTotal = opts.sections
    ? opts.sections.closingSoonTotal ?? opts.sections.closingSoon?.length ?? 0
    : 0;
  const summaryHeadline =
    newCount > 0
      ? `${newCountLabel} new opportunit${newCount === 1 ? "y" : "ies"} for you`
      : `${closingTotal} opportunit${closingTotal === 1 ? "y" : "ies"} closing soon`;
  const logoImg = logoUrl
    ? `<img src="${escapeDigestHtml(logoUrl)}" alt="${escapeDigestHtml(brandName)}" height="28" style="height:28px;vertical-align:middle;border:0;" />`
    : "";
  const titleHtml = `<span style="color:#fff;font-size:20px;font-weight:700;letter-spacing:.01em;vertical-align:middle;${logoImg ? "margin-left:10px;" : ""}">${escapeDigestHtml(headerTitle)}</span>`;
  const headerHtml = `<tr><td style="background:${brandColor};padding:16px 20px;border-radius:8px 8px 0 0;">${logoImg}${titleHtml}</td></tr>`;

  // A short summary header above the list gives the email a scannable "what's here" line.
  const summaryHtml = `<p style="font-size:17px;font-weight:700;margin:0 0 4px;color:#1f2937;">${escapeDigestHtml(summaryHeadline)}</p>`;

  const html = `<div style="font-family:Arial,Helvetica,sans-serif;color:#333;max-width:600px;margin:0 auto;">
  <table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="border-collapse:collapse;">${headerHtml}
    <tr><td style="padding:20px;">
      ${summaryHtml}
      <p style="font-size:15px;margin-top:0;color:#4b5563;">${escapeDigestHtml(intro)}</p>
      <table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="border-collapse:collapse;">${rows}${overflowHtml}</table>
      ${footerLinkHtml}
      <p style="color:#6b7280;font-size:12px;margin-top:16px;">${escapeDigestHtml(footer)}</p>
      ${supportHtml}
      ${addressHtml}
    </td></tr>
  </table>
</div>`;

  return { subject, text, html };
}

// --- NOFO digest selection (pure; shared by digest send + Developer preview) ---
// The selection has two independent gates, applied per user against the pool of active NOFOs:
//   1. recency  — the NOFO turned up after the user's last_sent watermark
//   2. prefs    — the NOFO matches the user's state, and (if set) categories/keywords
// Both the scheduled send and the Developer preview run this exact logic so the preview
// reflects what a user would truly receive. Keep this the single source for that decision.

const DIGEST_LOOKBACK_DAYS = { daily: 1, weekly: 7 };

function digestArr(v) {
  return Array.isArray(v) ? v : [];
}

/**
 * The window start for a user: their last_sent watermark, or a frequency-based lookback
 * (1 day / 7 days before `now`) when there is no watermark yet. `now` is a Date.
 */
export function digestWatermark(lastSent, frequency, now) {
  if (lastSent) {
    const d = new Date(lastSent);
    if (!isNaN(d.getTime())) return d;
  }
  const fallback = new Date(now);
  fallback.setDate(fallback.getDate() - (DIGEST_LOOKBACK_DAYS[frequency] || 1));
  return fallback;
}

function digestCreatedAfter(nofo, since) {
  if (!nofo.created_at) return false;
  const d = new Date(nofo.created_at);
  return !isNaN(d.getTime()) && d > since;
}

/**
 * Whole-word (well, whole-phrase) keyword match against an already-lowercased haystack. A raw
 * `includes` gave false positives ("art" hitting "start"/"quarterly"); this requires the keyword
 * to sit on word boundaries. Regex metachars in the keyword are escaped so it stays a literal.
 */
function keywordMatches(haystack, keyword) {
  const needle = keyword.trim().toLowerCase();
  if (!needle) return false;
  const escaped = needle.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return new RegExp(`\\b${escaped}\\b`).test(haystack);
}

/**
 * True when a NOFO matches a user's topic prefs. State is a hard gate: a NOFO scoped to a
 * different state never matches; a NOFO with no state is national and always passes. With no
 * categories/keywords set, every in-state NOFO matches; otherwise it's an OR across category
 * membership and keyword substring hits on name+summary.
 */
export function matchesDigestPrefs(nofo, prefs) {
  return scoreDigestMatch(nofo, prefs).matched;
}

/**
 * The graded form of matchesDigestPrefs. State is still a hard gate. Returns:
 *   matched  — boolean, identical to matchesDigestPrefs
 *   score    — higher = stronger match; a category hit outweighs keyword hits, and each extra
 *              keyword adds a little. Used to rank grants within a digest section.
 *   reasons  — human-readable match reasons ("Category: Environment", 'Keyword: "climate"'),
 *              surfaced per-grant so the reader sees why it was included.
 * With no prefs set, every in-state NOFO matches with score 0 and no specific reason.
 */
export function scoreDigestMatch(nofo, prefs) {
  const none = { matched: false, score: 0, reasons: [] };
  const userState = String(prefs.state || "").toUpperCase();
  const nofoState = String(nofo.state || "").toUpperCase();
  if (userState && nofoState && nofoState !== userState) return none;

  const categories = digestArr(prefs.categories);
  const keywords = digestArr(prefs.keywords);
  if (!categories.length && !keywords.length) {
    return { matched: true, score: 0, reasons: [] };
  }

  let score = 0;
  const reasons = [];
  if (categories.length && nofo.category && categories.includes(nofo.category)) {
    score += 10;
    reasons.push(`Category: ${nofo.category}`);
  }
  if (keywords.length) {
    const haystack = `${nofo.nofo_name || ""} ${nofo.summary || ""}`.toLowerCase();
    // Whole-word match, not raw substring: keyword "art" must not fire on "start"/"quarterly".
    for (const k of keywords) {
      if (keywordMatches(haystack, String(k))) {
        score += 3;
        reasons.push(`Keyword: "${k}"`);
      }
    }
  }
  return { matched: score > 0, score, reasons };
}

/**
 * The NOFOs a user should receive this run: from `activeNofos`, those created after their
 * watermark and matching their prefs. Returns { matches, since } so callers can advance the
 * watermark and/or render the digest's date range.
 */
export function selectDigestNofos(activeNofos, prefs, frequency, now) {
  const since = digestWatermark(prefs.last_sent, frequency, now);
  const matches = (activeNofos || []).filter(
    (nofo) => digestCreatedAfter(nofo, since) && matchesDigestPrefs(nofo, prefs)
  );
  return { matches, since };
}

// How soon (in days) a deadline must be to count as "closing soon".
const DIGEST_CLOSING_SOON_DAYS = 30;

function digestDaysUntil(dateValue, now) {
  if (!dateValue) return null;
  const d = /^\d{4}-\d{2}-\d{2}$/.test(dateValue)
    ? new Date(`${dateValue}T00:00:00Z`)
    : new Date(dateValue);
  if (isNaN(d.getTime())) return null;
  return Math.ceil((d.getTime() - now.getTime()) / 86400000);
}

/**
 * Sectioned selection for the richer digest. Every pref-matching in-state NOFO is graded, then
 * split so an empty "new" set doesn't mean an empty email:
 *   new         — matches created after the user's watermark (the classic digest content)
 *   closingSoon — matches NOT new, but with a deadline within DIGEST_CLOSING_SOON_DAYS (and not past)
 *   stillOpen   — remaining matches
 * Each grant carries { score, reasons, daysUntil }. Within a section, sort is match-strength first
 * (score desc), deadline as the tiebreaker (soonest first). Callers decide whether to send: if all
 * three sections are empty there is genuinely nothing relevant and the send can be skipped.
 *
 * A combined `displayCap` (default 10) bounds how many grants the email actually shows — a 60-match
 * week must not render 60 cards. Slots fill by section priority (New, then Closing soon, then Still
 * open), so the most relevant grants survive the cut. The returned sections hold only the shown
 * items; `newTotal`/`closingSoonTotal`/`stillOpenTotal` are the true pre-cap counts and `overflow`
 * is how many matching grants were left out (drives a "view all" link).
 */
export function selectDigestSections(activeNofos, prefs, frequency, now, opts = {}) {
  const since = digestWatermark(prefs.last_sent, frequency, now);
  const displayCap = Number.isInteger(opts.displayCap) ? opts.displayCap : 10;

  const graded = [];
  for (const nofo of activeNofos || []) {
    const { matched, score, reasons } = scoreDigestMatch(nofo, prefs);
    if (!matched) continue;
    graded.push({ nofo, score, reasons, daysUntil: digestDaysUntil(nofo.expiration_date, now) });
  }

  const byStrengthThenDeadline = (a, b) => {
    if (b.score !== a.score) return b.score - a.score;
    const ad = a.daysUntil == null ? Infinity : a.daysUntil;
    const bd = b.daysUntil == null ? Infinity : b.daysUntil;
    return ad - bd;
  };

  const isNew = (g) => digestCreatedAfter(g.nofo, since);
  const isClosingSoon = (g) =>
    g.daysUntil != null && g.daysUntil >= 0 && g.daysUntil <= DIGEST_CLOSING_SOON_DAYS;

  const newAll = graded.filter(isNew).sort(byStrengthThenDeadline);
  const rest = graded.filter((g) => !isNew(g));
  const closingAll = rest.filter(isClosingSoon).sort(byStrengthThenDeadline);
  const closingSet = new Set(closingAll);
  const openAll = rest.filter((g) => !closingSet.has(g)).sort(byStrengthThenDeadline);

  // Fill the combined display budget by priority: New first, then Closing soon, then Still open.
  let budget = Math.max(0, displayCap);
  const take = (arr) => {
    const n = Math.min(budget, arr.length);
    budget -= n;
    return arr.slice(0, n);
  };
  const newItems = take(newAll);
  const closingSoon = take(closingAll);
  const stillOpen = take(openAll);

  const matchTotal = newAll.length + closingAll.length + openAll.length;
  const shownTotal = newItems.length + closingSoon.length + stillOpen.length;
  return {
    since,
    new: newItems,
    closingSoon,
    stillOpen,
    total: shownTotal,
    newTotal: newAll.length,
    closingSoonTotal: closingAll.length,
    stillOpenTotal: openAll.length,
    matchTotal,
    overflow: matchTotal - shownTotal,
  };
}
